'use strict';
(() => {
  const $ = id => document.getElementById(id);
  const input=$('scenario'), output=$('results'), status=$('status');
  let revision=0, current=null;
  function say(message,error=false){status.textContent=message;status.className=error?'status error':'status';}
  function invalidate(){revision++;current=null;output.replaceChildren();$('export').disabled=true;$('review').checked=false;$('review').disabled=true;$('fingerprint').textContent='—';for(const id of ['applied','denied','replayed'])$(id).textContent='—';say('ข้อมูลเปลี่ยนแล้ว กรุณาประมวลผลใหม่');}
  function element(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(className)e.className=className;return e;}
  function table(headers,rows){const wrap=element('div',undefined,'table-wrap');const t=element('table');const head=element('thead'),tr=element('tr');headers.forEach(h=>tr.append(element('th',h)));head.append(tr);t.append(head);const body=element('tbody');for(const row of rows){const r=element('tr');row.forEach(value=>r.append(element('td',value)));body.append(r);}t.append(body);wrap.append(t);return wrap;}
  function section(title,result){const panel=element('section',undefined,'panel');panel.append(element('h3',title));const line=element('p',`${result.summary.applied} applied · ${result.summary.denied} denied · ${result.summary.replayed} replayed`,'hint');panel.append(line);const inv=element('div');for(const [name,passed] of Object.entries(result.invariants)){inv.append(element('p',`${passed?'PASS':'FAIL'} · ${name}`,passed?'pass':'fail'));}panel.append(inv);panel.append(table(['#','เหตุการณ์','ผล','เหตุผล'],result.timeline.map(e=>[e.event,e.type,e.status,e.reason])));panel.append(element('h3','สถานะหลัง Replay'));panel.append(table(['บัญชี','ยอดเงิน','ไอเทม'],Object.entries(result.state.accounts).map(([id,a])=>[id,a.balance,JSON.stringify(a.inventory)])));panel.append(element('p',`Treasury ${result.state.treasury} · Total ${result.finalCurrencyTotal}`,'hint'));panel.append(table(['ร้านค้า','ราคา','คงเหลือ'],Object.entries(result.state.shop).map(([id,i])=>[id,i.price,i.stock])));return panel;}
  input.addEventListener('input',invalidate);
  $('preset').addEventListener('change',()=>{input.value=GameGuard.sample($('preset').value);invalidate();say('โหลดสถานการณ์สมมติแล้ว กดเปรียบเทียบเพื่อดูผล');});
  $('sample').addEventListener('click',()=>{input.value=GameGuard.sample($('preset').value);invalidate();say('โหลดสถานการณ์สมมติแล้ว');});
  $('clear').addEventListener('click',()=>{input.value='';$('file').value='';invalidate();say('ล้างข้อมูลแล้ว');});
  $('run').addEventListener('click',async()=>{invalidate();const active=revision,text=input.value;say('กำลังตรวจและคำนวณ SHA-256…');try{const r=await GameGuard.report(text);if(active!==revision)return;current={...r,sourceSha256:typeof GameGuardProvenance==='object'?GameGuardProvenance.engineSha256:null};output.append(section('NAIVE / ไม่มีการ์ด',r.naive),section('GUARDED / ตรวจทุกเหตุการณ์',r.guarded));for(const id of ['applied','denied','replayed'])$(id).textContent=r.guarded.summary[id];$('review').disabled=false;say('เปรียบเทียบแล้ว · รายงานมีสถานะบัญชีและไอเทม กรุณาตรวจทานก่อนส่งออก');$('fingerprint').textContent=r.fixtureSha256;}catch(error){if(active!==revision)return;say(error instanceof GameGuard.GuardError?error.message:'ไม่สามารถประมวลผลได้ กรุณาตรวจรูปแบบข้อมูล',true);}});
  $('review').addEventListener('change',()=>{$('export').disabled=!current||!$('review').checked;});
  $('export').addEventListener('click',()=>{if(!current||!$('review').checked)return;const blob=new Blob([JSON.stringify(current,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const a=element('a');a.href=url;a.download='gameguard-report.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);say('ดาวน์โหลดรายงานแล้ว');});
  $('file').addEventListener('change',async()=>{invalidate();const active=revision,f=$('file').files[0];if(!f)return;try{if(f.size>GameGuard.limits.maxBytes)throw new Error();const bytes=await f.arrayBuffer();const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);if(active!==revision)return;input.value=text;say('นำเข้าไฟล์แล้ว กรุณาประมวลผล');}catch{if(active===revision)say('ไฟล์ต้องเป็น UTF-8 JSON และขนาดไม่เกิน 256 KiB',true);}finally{$('file').value='';}});
  input.value=GameGuard.sample('replay');say('เริ่มจาก Replay จำลอง หรือแก้ไขสถานการณ์ของคุณ');
})();
